function validate([nums]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v !== 0 && v !== 1 && v !== 2)) return 'Every value is 0, 1 or 2.';
  return null;
}

