function countSpecialSubsequences(nums) {
  const MOD = 1000000007;
  let zeros = 0;
  let ones = 0;
  let twos = 0;
  for (const num of nums) {
    if (num === 0) {
      zeros = (2 * zeros + 1) % MOD;
    } else if (num === 1) {
      ones = (2 * ones + zeros) % MOD;
    } else {
      twos = (2 * twos + ones) % MOD;
    }
  }
  return twos;
}

