function countSpecialSubsequences(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  // finish[i][s]: ways to complete a subsequence whose last value is s - 1 (s = 0: nothing picked yet),
  // choosing its next element at some index j >= i, or stopping when it already ends in a 2.
  const finish = Array.from({ length: n + 1 }, () => [0, 0, 0, 0]);
  for (let i = n; i >= 0; i--) {
    for (let s = 0; s < 4; s++) {
      let total = s === 3 ? 1 : 0;
      for (let j = i; j < n; j++) {
        if (nums[j] === s - 1 || nums[j] === s) total = (total + finish[j + 1][nums[j] + 1]) % MOD;
      }
      finish[i][s] = total;
    }
  }
  return finish[0][0];
}

