function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(12);
  if (rand() < 0.3) {
    // Mostly in order: a few blocks of 0s, 1s and 2s.
    return [Array.from({ length: n }, (_, i) => (rand() < 0.15 ? pick(3) : Math.floor((3 * i) / n)))];
  }
  return [Array.from({ length: n }, () => pick(3))];
}
